import { ApiError, type OrdersController, type PaymentsController } from "@paypal/paypal-server-sdk";
import type { PayPalApi, PayPalOut, Rest } from "@/lib/payments/types";

/**
 * Every Orders and Payments call goes through the PayPal Server SDK (generated by APIMatic), each as a direct method
 * on its controller: creating, reading and capturing orders, reading captures, refunding them and reading refunds.
 * The SDK covers neither Payouts nor Transaction Search, Disputes or webhook verification, so those stay on REST.
 *
 * The payments engine speaks PayPal's own JSON (snake_case), the shape its fake for tests also speaks. `sdkApi` keeps
 * that contract: request bodies are mapped to the SDK's property names, and the answer is PayPal's response body as
 * sent. `restApi` gives the same six calls over a REST client, which is how the tests' fake PayPal answers them.
 */
const camel = (key: string) => key.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase());

/** PayPal's JSON names to the SDK's property names, at every depth. Values (enums, amounts, ids) are untouched. */
export function toSdkShape(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(toSdkShape);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value as Record<string, unknown>).map(([k, v]) => [camel(k), toSdkShape(v)]));
  }
  return value;
}

function parse(body: unknown): unknown {
  if (typeof body !== "string" || !body.trim()) return {};
  try {
    return JSON.parse(body);
  } catch {
    return {};
  }
}

const header = (headers: Record<string, string> | undefined, name: string) => {
  if (!headers) return null;
  const k = Object.keys(headers).find((h) => h.toLowerCase() === name);
  return k ? headers[k] : null;
};

export type Controllers = { orders: () => OrdersController; payments: () => PaymentsController };
type SdkResponse = { statusCode: number; body: unknown; headers: Record<string, string> };

/** The six calls on the SDK's own controllers. Each attempt carries its PayPal-Request-Id, so a retry returns the first answer. */
export function sdkApi(ctrl: Controllers): PayPalApi {
  const prefer = "return=representation";
  const run = async <T>(call: () => Promise<SdkResponse>): Promise<PayPalOut<T>> => {
    try {
      const res = await call();
      return { status: res.statusCode, body: parse(res.body) as T, debugId: header(res.headers, "paypal-debug-id") };
    } catch (e) {
      if (e instanceof ApiError) return { status: e.statusCode, body: parse(e.body) as T, debugId: header(e.headers, "paypal-debug-id") };
      throw e;
    }
  };
  return {
    createOrder: (body, o = {}) => run(() => ctrl.orders().createOrder({ body: toSdkShape(body) as never, paypalRequestId: o.requestId, prefer, paypalMockResponse: o.mock })),
    getOrder: (id) => run(() => ctrl.orders().getOrder({ id })),
    captureOrder: (id, o = {}) => run(() => ctrl.orders().captureOrder({ id, paypalRequestId: o.requestId, prefer, paypalMockResponse: o.mock })),
    getCapture: (captureId) => run(() => ctrl.payments().getCapturedPayment({ captureId })),
    refundCapture: (captureId, body, o) => run(() => ctrl.payments().refundCapturedPayment({ captureId, paypalRequestId: o.requestId, prefer, paypalMockResponse: o.mock, body: toSdkShape(body) as never })),
    getRefund: (refundId) => run(() => ctrl.payments().getRefund({ refundId })),
  };
}

/** The same six calls over a REST client: the tests' fake PayPal, or an account without the SDK. Same paths, same headers. */
export function restApi(rest: Rest): PayPalApi {
  const enc = encodeURIComponent;
  const headers = (o: { mock?: string }) => ({ Prefer: "return=representation", ...(o.mock ? { "PayPal-Mock-Response": JSON.stringify({ mock_application_codes: o.mock }) } : {}) });
  return {
    createOrder: (body, o = {}) => rest("/v2/checkout/orders", { method: "POST", requestId: o.requestId, headers: headers(o), body: JSON.stringify(body) }),
    getOrder: (id) => rest(`/v2/checkout/orders/${enc(id)}`, { method: "GET" }),
    captureOrder: (id, o = {}) => rest(`/v2/checkout/orders/${enc(id)}/capture`, { method: "POST", requestId: o.requestId, headers: headers(o) }),
    getCapture: (captureId) => rest(`/v2/payments/captures/${enc(captureId)}`, { method: "GET" }),
    refundCapture: (captureId, body, o) => rest(`/v2/payments/captures/${enc(captureId)}/refund`, { method: "POST", requestId: o.requestId, headers: headers(o), body: JSON.stringify(body) }),
    getRefund: (refundId) => rest(`/v2/payments/refunds/${enc(refundId)}`, { method: "GET" }),
  };
}

/** An account's Orders and Payments calls: the SDK it carries, else the same calls over its REST client. */
export const paypalApiOf = (rest: Rest): PayPalApi => rest.paypal ?? restApi(rest);
